def f(inputs: List[Tuple[int, str]]):
    def eval_expr(expr):
        stack = []
        for c in expr:
            if c == '(':
                stack.append('(')
            elif c == ')':
                val = stack.pop()
                while stack and stack[-1]!= '(':
                    val = stack.pop() * val
                stack.pop()  # remove '('
            else:
                stack.append(int(c))
        return stack[0]

    for n, expr in inputs:
        print(eval_expr(expr))
```

